// Share normalizer: parts sum to 100 with explicit other (plain JS)
function shares(parts) {
  const total = parts.reduce((s, p) => s + p.value, 0);
  const out = parts.map((p) => ({ ...p, pct: (p.value / total) * 100 }));
  const sum = out.reduce((s, p) => s + p.pct, 0);
  return { parts: out, check: Math.abs(sum - 100) < 1e-9 };
}
// Overlaps (multi-category items) must NOT sum to 100 silently: state basis
// (share of revenue vs share of items) or split attributions explicitly.

